import {
  ApiError,
  CheckoutPaymentIntent,
  Client,
  Environment,
  OrdersController,
  PaymentsController,
  PaypalExperienceUserAction,
  PaypalWalletContextShippingPreference,
} from "@paypal/paypal-server-sdk";

// PayPal access. Orders and Payments go through PayPal's official TypeScript
// server SDK (generated by APIMatic). Webhook signature verification is not in
// that SDK, so it uses the REST endpoint directly.

const BASE =
  process.env.PAYPAL_ENV === "live" ? "https://api-m.paypal.com" : "https://api-m.sandbox.paypal.com";

export function paypalConfigured(): boolean {
  return Boolean(process.env.PAYPAL_CLIENT_ID && process.env.PAYPAL_CLIENT_SECRET);
}

export function webhookConfigured(): boolean {
  return paypalConfigured() && Boolean(process.env.PAYPAL_WEBHOOK_ID);
}

export class PayPalError extends Error {
  status: number;
  constructor(message: string, status = 500) {
    super(message);
    this.status = status;
  }
}

type G = typeof globalThis & { __ppClient?: Client; __ppToken?: { value: string; exp: number } };
const g = globalThis as G;

function client(): Client {
  if (!paypalConfigured()) {
    throw new PayPalError("PayPal is not configured. Set PAYPAL_CLIENT_ID and PAYPAL_CLIENT_SECRET.", 503);
  }
  if (!g.__ppClient) {
    g.__ppClient = new Client({
      clientCredentialsAuthCredentials: {
        oAuthClientId: process.env.PAYPAL_CLIENT_ID as string,
        oAuthClientSecret: process.env.PAYPAL_CLIENT_SECRET as string,
      },
      environment: process.env.PAYPAL_ENV === "live" ? Environment.Production : Environment.Sandbox,
      timeout: 20000,
    });
  }
  return g.__ppClient;
}

function wrap(err: unknown): PayPalError {
  if (err instanceof PayPalError) return err;
  if (err instanceof ApiError) {
    let message = `PayPal API error ${err.statusCode}`;
    try {
      const body = typeof err.body === "string" ? JSON.parse(err.body) : err.body;
      const b = body as { message?: string; name?: string; details?: { issue?: string }[] };
      const issue = b?.details?.[0]?.issue;
      message = [b?.name, issue, b?.message].filter(Boolean).join(": ") || message;
    } catch {
      /* keep default */
    }
    return new PayPalError(message, err.statusCode);
  }
  return new PayPalError(err instanceof Error ? err.message : String(err));
}

/* eslint-disable @typescript-eslint/no-explicit-any */
export type RawOrder = any;
export type RawCapture = any;

function raw(res: { body: unknown; result: unknown }): any {
  // Use the wire JSON (snake_case, exactly as documented in PayPal's REST reference).
  if (typeof res.body === "string" && res.body.length) {
    try {
      return JSON.parse(res.body);
    } catch {
      /* fall through */
    }
  }
  return res.result;
}

export interface CreateOrderInput {
  quoteId: string;
  description: string;
  amountValue: string;
  requestId: string;
  returnUrl: string;
  cancelUrl: string;
}

export async function createOrder(input: CreateOrderInput): Promise<RawOrder> {
  try {
    const res = await new OrdersController(client()).createOrder({
      body: {
        intent: CheckoutPaymentIntent.Capture,
        purchaseUnits: [
          {
            referenceId: input.quoteId,
            customId: input.quoteId,
            invoiceId: input.quoteId,
            description: input.description.slice(0, 120),
            amount: { currencyCode: "USD", value: input.amountValue },
          },
        ],
        paymentSource: {
          paypal: {
            experienceContext: {
              brandName: "Counter demo store",
              userAction: "PAY_NOW" as PaypalExperienceUserAction,
              shippingPreference: "NO_SHIPPING" as PaypalWalletContextShippingPreference,
              returnUrl: input.returnUrl,
              cancelUrl: input.cancelUrl,
            },
          },
        },
      },
      // Idempotency: the same signed quote can never create two different orders.
      paypalRequestId: input.requestId,
      prefer: "return=representation",
    });
    return raw(res);
  } catch (err) {
    throw wrap(err);
  }
}

export async function getOrder(id: string): Promise<RawOrder> {
  try {
    return raw(await new OrdersController(client()).getOrder({ id }));
  } catch (err) {
    throw wrap(err);
  }
}

export async function captureOrder(id: string): Promise<RawOrder> {
  try {
    return raw(
      await new OrdersController(client()).captureOrder({ id, prefer: "return=representation" })
    );
  } catch (err) {
    throw wrap(err);
  }
}

/** Returns null when PayPal has no such capture on this account. */
export async function getCapture(captureId: string): Promise<RawCapture | null> {
  try {
    return raw(await new PaymentsController(client()).getCapturedPayment({ captureId }));
  } catch (err) {
    const e = wrap(err);
    if (e.status === 404 || e.status === 400 || e.status === 403 || e.status === 422) return null;
    throw e;
  }
}

export async function refundCapture(captureId: string, note: string): Promise<any> {
  try {
    return raw(
      await new PaymentsController(client()).refundCapturedPayment({
        captureId,
        prefer: "return=representation",
        body: { noteToPayer: note.slice(0, 250) },
      })
    );
  } catch (err) {
    throw wrap(err);
  }
}

async function accessToken(): Promise<string> {
  if (g.__ppToken && g.__ppToken.exp > Date.now() + 30_000) return g.__ppToken.value;
  const basic = Buffer.from(`${process.env.PAYPAL_CLIENT_ID}:${process.env.PAYPAL_CLIENT_SECRET}`).toString("base64");
  const res = await fetch(`${BASE}/v1/oauth2/token`, {
    method: "POST",
    headers: { Authorization: `Basic ${basic}`, "Content-Type": "application/x-www-form-urlencoded" },
    body: "grant_type=client_credentials",
  });
  if (!res.ok) throw new PayPalError(`PayPal token request failed (${res.status})`, res.status);
  const json = (await res.json()) as { access_token: string; expires_in: number };
  g.__ppToken = { value: json.access_token, exp: Date.now() + json.expires_in * 1000 };
  return json.access_token;
}

export interface WebhookHeaders {
  transmissionId: string | null;
  transmissionTime: string | null;
  transmissionSig: string | null;
  certUrl: string | null;
  authAlgo: string | null;
}

/**
 * Asks PayPal whether a webhook really came from PayPal.
 * The raw event body is spliced in untouched: re-serialising the JSON can
 * change byte order or number formatting and make a genuine event fail.
 */
export async function verifyWebhookSignature(rawBody: string, h: WebhookHeaders): Promise<boolean> {
  if (!webhookConfigured()) return false;
  if (!h.transmissionId || !h.transmissionTime || !h.transmissionSig || !h.certUrl || !h.authAlgo) return false;
  try {
    JSON.parse(rawBody);
  } catch {
    return false;
  }
  const envelope = JSON.stringify({
    auth_algo: h.authAlgo,
    cert_url: h.certUrl,
    transmission_id: h.transmissionId,
    transmission_sig: h.transmissionSig,
    transmission_time: h.transmissionTime,
    webhook_id: process.env.PAYPAL_WEBHOOK_ID,
  });
  const body = `${envelope.slice(0, -1)},"webhook_event":${rawBody}}`;
  const res = await fetch(`${BASE}/v1/notifications/verify-webhook-signature`, {
    method: "POST",
    headers: { Authorization: `Bearer ${await accessToken()}`, "Content-Type": "application/json" },
    body,
  });
  if (!res.ok) return false;
  const json = (await res.json()) as { verification_status?: string };
  return json.verification_status === "SUCCESS";
}
